import { TASK, TAKEOFF, GATES, PAD, random, trialParameters, SPLITS } from '/workspace/tasks/drone/task.mjs';
import { validateSource, initialState } from '/workspace/tasks/drone/sim.mjs';
import { resolve } from 'node:path';

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const norm = (v) => Math.hypot(v.x, v.y, v.z);
const copy = (v) => ({ ...v });
const MOTOR_X = [-1, 1, 1, -1], MOTOR_Z = [-1, -1, 1, -1], SPIN = [1, -1, 1, -1];

function observation(state, rng) {
  const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
  const vector = (v, n) => Object.fromEntries(Object.entries(v).map(([key, value]) => [key, value + noise(n)]));
  return {
    t: +state.t.toFixed(4), pos: vector(state.pos, TASK.positionNoise), vel: vector(state.vel, TASK.velocityNoise),
    att: vector(state.att, TASK.attitudeNoise), rates: vector(state.rates, TASK.rateNoise),
    gateIndex: state.gateIndex,
    nextGate: state.gateIndex < GATES.length ? { centre: copy(GATES[state.gateIndex].centre), normal: copy(GATES[state.gateIndex].normal) } : null,
    pad: { centre: copy(PAD.centre) },
  };
}

function integrate(state, action, parameters, dt) {
  const old = copy(state.pos), { att, rates } = state;
  const inertia = TASK.inertia * parameters.mass / TASK.baseMass;
  const torque = {};
  for (const axis of ['roll', 'pitch']) {
    const error = action[axis] - att[axis];
    state.integral[axis] = clamp(state.integral[axis] + error * dt, -0.35, 0.35);
    torque[axis] = inertia * (65 * error - 13 * rates[axis] + 22 * state.integral[axis]);
  }
  torque.yaw = inertia * 8 * (action.yawRate - rates.yaw);
  for (let i = 0; i < 4; i++) {
    const desired = action.thrust * TASK.maxMotorThrust +
      torque.roll * MOTOR_Z[i] / (4 * TASK.arm) - torque.pitch * MOTOR_X[i] / (4 * TASK.arm) +
      torque.yaw * SPIN[i] / (4 * TASK.yawCoefficient);
    const target = clamp(desired, 0, TASK.maxMotorThrust) * (i === parameters.weakMotor ? 1 - parameters.weakness : 1);
    state.motors[i] += (target - state.motors[i]) * (1 - Math.exp(-dt / parameters.lag));
  }
  const sum = state.motors.reduce((a, b) => a + b, 0);
  const moment = (sign) => state.motors.reduce((a, f, i) => a + f * sign[i], 0);
  rates.roll += (TASK.arm * moment(MOTOR_Z) / inertia - 0.4 * rates.roll) * dt;
  rates.pitch += (-TASK.arm * moment(MOTOR_X) / inertia - 0.4 * rates.pitch) * dt;
  rates.yaw += (TASK.yawCoefficient * moment(SPIN) / inertia - 0.4 * rates.yaw) * dt;
  for (const axis of ['roll', 'pitch', 'yaw']) att[axis] += rates[axis] * dt;
  const bodyX = Math.sin(att.pitch) * Math.cos(att.roll), bodyZ = -Math.sin(att.roll);
  const direction = { x: Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ,
    y: Math.cos(att.pitch) * Math.cos(att.roll), z: -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ };
  const wind = copy(parameters.baseWind);
  for (const gust of parameters.gusts) if (state.t >= gust.start && state.t < gust.start + gust.duration) {
    wind.x += gust.x; wind.y += gust.y; wind.z += gust.z;
  }
  for (const axis of ['x', 'y', 'z']) {
    const force = sum * direction[axis] + TASK.linearDrag * (wind[axis] - state.vel[axis]);
    state.vel[axis] += (force / parameters.mass - (axis === 'y' ? TASK.gravity : 0)) * dt;
    state.pos[axis] += state.vel[axis] * dt;
  }
  state.t += dt;
  if (state.pos.y > TASK.bodyHeight + 0.08) state.airborne = true;
  if (Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.flipAngle) state.reason = 'flipped';
  if (Math.abs(state.pos.x) + TASK.bodyRadius >= TASK.room.maxX || Math.abs(state.pos.z) + TASK.bodyRadius >= TASK.room.maxZ || state.pos.y + TASK.bodyHeight >= TASK.room.height) {
    if (norm(state.vel) > TASK.contactCrashSpeed) state.reason = 'wall or ceiling crash';
    state.pos.x = clamp(state.pos.x, TASK.room.minX + TASK.bodyRadius, TASK.room.maxX - TASK.bodyRadius);
    state.pos.z = clamp(state.pos.z, TASK.room.minZ + TASK.bodyRadius, TASK.room.maxZ - TASK.bodyRadius);
    state.pos.y = Math.min(state.pos.y, TASK.room.height - TASK.bodyHeight);
    state.vel.x = 0; state.vel.z = 0; state.vel.y = Math.min(state.vel.y, 0);
  }
  if (state.pos.y <= TASK.bodyHeight) {
    if (state.airborne && (norm(state.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.landingTilt * 2)) state.reason = 'floor crash';
    state.pos.y = TASK.bodyHeight; state.vel.y = Math.max(0, state.vel.y);
    state.vel.x *= Math.exp(-12 * dt); state.vel.z *= Math.exp(-12 * dt);
  }
  for (let i = 0; i < GATES.length; i++) {
    const gate = GATES[i], x = gate.centre.x;
    if ((old.x < x && state.pos.x >= x) || (old.x > x && state.pos.x <= x)) {
      const fraction = (x - old.x) / (state.pos.x - old.x);
      const y = old.y + fraction * (state.pos.y - old.y), z = old.z + fraction * (state.pos.z - old.z);
      const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
      const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
      const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
      const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
      if (overlapsFrame) state.reason = 'gate frame collision';
      if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
    }
  }
  const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
  if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
      norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
  else state.landedFor = 0;
  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = 'landed';
}

const file = resolve(process.argv[2] || '/workspace/controller.js');
validateSource(file);
const mod = await import(file + '?t=' + Date.now());
const makeController = mod.default;

function runFast(seed) {
  const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const controller = makeController();
  for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
    const raw = controller.step(observation(state, rng));
    const action = {
      thrust: clamp(raw.thrust, 0, 1), roll: clamp(raw.roll, -0.6, 0.6),
      pitch: clamp(raw.pitch, -0.6, 0.6), yawRate: clamp(raw.yawRate, -2, 2)
    };
    for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
  }
  return {
    seed, success: state.reason === 'landed', reason: state.reason || 'time limit', gatesPassed: state.gateIndex,
    landingError: +Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z).toFixed(4),
    simulatedSeconds: +state.t.toFixed(3), pos: state.pos
  };
}

const smoke = SPLITS.smoke.map(runFast);
console.log('SMOKE:', smoke.filter(r => r.success).length + '/4');
for (const r of smoke) console.log(' ', r.seed, r.success ? 'PASS' : 'FAIL', r.reason, `gates=${r.gatesPassed}/3`, `err=${r.landingError}`, `t=${r.simulatedSeconds}s`);

const N = Number(process.argv[3] || 200);
const results = [];
const reasons = {};
for (let s = 1; s <= N; s++) {
  const r = runFast(s);
  results.push(r);
  if (!r.success) reasons[r.reason + ` (g${r.gatesPassed})`] = (reasons[r.reason + ` (g${r.gatesPassed})`] || 0) + 1;
}
const passed = results.filter(r => r.success).length;
console.log(`BENCH (1..${N}): ${passed}/${N} (${(100*passed/N).toFixed(1)}%)`);
console.log('Failures:', reasons);
for (const r of results.filter(r => !r.success).slice(0, 15)) {
  console.log('  fail seed', r.seed, r.reason, `gates=${r.gatesPassed}/3`, `err=${r.landingError}`, `t=${r.simulatedSeconds}s`, `pos=(${r.pos.x.toFixed(2)},${r.pos.y.toFixed(2)},${r.pos.z.toFixed(2)})`);
}

export default function makeController() {
  const dt = 0.01;
  const g = 9.81;
  const nomMass = 0.72;
  const dragCoeff = 0.42;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let vf = { x: 0, y: 0, z: 0 };
  let prevVf = { x: 0, y: 0, z: 0 };
  let distSlow = { x: 0, y: 0, z: 0 };
  let distFast = { x: 0, y: 0, z: 0 };
  let motorThrust = 0.45;
  let lastThrust = 0.45;

  let yawInt = 0;
  let posInt = { x: 0, y: 0, z: 0 };
  let ref = { x: 0, y: 0, z: 0 };

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let lockedGate = null;
  let exitTimer = 0;
  let descentY = 0.75;

  return {
    step(obs) {
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vf = { x: v.x, y: v.y, z: v.z };
        prevVf = { x: v.x, y: v.y, z: v.z };
        ref = { x: p.x, y: Math.max(p.y, 0.35), z: p.z };
        motorThrust = (nomMass * g) / 16;
        lastThrust = motorThrust;
      }

      // 1. Filter velocity
      const alphaV = 0.4;
      vf.x += alphaV * (v.x - vf.x);
      vf.y += alphaV * (v.y - vf.y);
      vf.z += alphaV * (v.z - vf.z);

      // 2. Fast/slow acceleration disturbance observer
      const aMeas = {
        x: (vf.x - prevVf.x) / dt,
        y: (vf.y - prevVf.y) / dt,
        z: (vf.z - prevVf.z) / dt,
      };
      prevVf.x = vf.x;
      prevVf.y = vf.y;
      prevVf.z = vf.z;

      motorThrust += (lastThrust - motorThrust) * (1 - Math.exp(-dt / 0.04));
      const specThrust = (16 * motorThrust) / nomMass;
      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

      const dragAcc = dragCoeff / nomMass;
      const aModel = {
        x: specThrust * dirX - dragAcc * vf.x,
        y: specThrust * dirY - g - dragAcc * vf.y,
        z: specThrust * dirZ - dragAcc * vf.z,
      };

      if (obs.t > 0.08 && p.y > 0.085) {
        const rawDistX = clamp(aMeas.x - aModel.x, -8, 8);
        const rawDistY = clamp(aMeas.y - aModel.y, -6, 6);
        const rawDistZ = clamp(aMeas.z - aModel.z, -8, 8);

        const alphaSlow = 0.035;
        const alphaFast = 0.22;
        distSlow.x += alphaSlow * (rawDistX - distSlow.x);
        distSlow.y += alphaSlow * (rawDistY - distSlow.y);
        distSlow.z += alphaSlow * (rawDistZ - distSlow.z);

        distFast.x += alphaFast * (rawDistX - distFast.x);
        distFast.y += alphaFast * (rawDistY - distFast.y);
        distFast.z += alphaFast * (rawDistZ - distFast.z);
      }

      // 5 & 6 & 7. Navigation state machine: gate exit lock, predictive cross abort, ramp pad descent
      let target;
      if (phase === 'exitLock' && lockedGate) {
        exitTimer += dt;
        target = { x: lockedGate.x + 0.32, y: lockedGate.y, z: lockedGate.z };
        if (p.x >= lockedGate.x + 0.18 || exitTimer > 0.28) {
          phase = 'align';
          lockedGate = null;
          settle = 0;
        }
      }

      if (phase !== 'exitLock') {
        if (obs.gateIndex < 3) {
          const gate = obs.nextGate.centre;
          if (targetIndex !== obs.gateIndex) {
            if (targetIndex >= 0 && lockedGate && p.x < lockedGate.x + 0.16) {
              targetIndex = obs.gateIndex;
              phase = 'exitLock';
              exitTimer = 0;
              target = { x: lockedGate.x + 0.32, y: lockedGate.y, z: lockedGate.z };
            } else {
              targetIndex = obs.gateIndex;
              phase = 'align';
              settle = 0;
              lockedGate = null;
            }
          }

          if (phase !== 'exitLock') {
            const alignX = gate.x - 0.42;
            if (phase === 'align') {
              target = { x: alignX, y: gate.y, z: gate.z };
              const errX = Math.abs(target.x - p.x);
              const errY = Math.abs(target.y - p.y);
              const errZ = Math.abs(target.z - p.z);
              const spd = Math.hypot(vf.x, vf.y, vf.z);
              const gustMag = Math.hypot(distFast.x - distSlow.x, distFast.z - distSlow.z);
              if (errX < 0.11 && errY < 0.08 && errZ < 0.055 && spd < 0.32 && gustMag < 1.1) {
                settle++;
              } else {
                settle = Math.max(0, settle - 1);
              }
              if (settle >= 10) {
                phase = 'cross';
                lockedGate = { x: gate.x, y: gate.y, z: gate.z };
              }
            }

            if (phase === 'cross') {
              lockedGate = { x: gate.x, y: gate.y, z: gate.z };
              target = { x: gate.x + 0.35, y: gate.y, z: gate.z };

              // Predictive cross abort before point of no return
              const dxGate = gate.x - p.x;
              if (dxGate > 0.11) {
                const tCross = clamp(dxGate / Math.max(vf.x, 0.25), 0.05, 0.45);
                const zPred = p.z + vf.z * tCross + 0.25 * (distFast.z - distSlow.z) * tCross * tCross;
                const yPred = p.y + vf.y * tCross + 0.25 * (distFast.y - distSlow.y) * tCross * tCross;
                const errZNow = Math.abs(p.z - gate.z);
                const errYNow = Math.abs(p.y - gate.y);
                if (
                  Math.abs(zPred - gate.z) > 0.082 ||
                  errZNow > 0.075 ||
                  Math.abs(yPred - gate.y) > 0.145 ||
                  errYNow > 0.135
                ) {
                  phase = 'align';
                  settle = 0;
                  target = { x: alignX, y: gate.y, z: gate.z };
                  ref.x = Math.min(ref.x, p.x);
                }
              }
            }
          }
        } else {
          // Pad approach and ramp descent
          const pad = obs.pad.centre;
          if (targetIndex !== 3) {
            targetIndex = 3;
            phase = 'padHover';
            descentY = Math.max(0.65, Math.min(0.9, p.y));
            posInt.x *= 0.3;
            posInt.z *= 0.3;
          }
          const errXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
          const spdXZ = Math.hypot(vf.x, vf.z);
          if (phase === 'padHover') {
            target = { x: pad.x, y: 0.72, z: pad.z };
            if (errXZ < 0.09 && spdXZ < 0.22 && Math.abs(p.y - 0.72) < 0.15) {
              phase = 'descend';
              descentY = p.y;
            }
          }
          if (phase === 'descend') {
            if (errXZ < 0.115) {
              const rate = p.y < 0.22 ? 0.28 : 0.52;
              descentY = Math.max(0.035, descentY - rate * dt);
            } else if (p.y > 0.13 && errXZ > 0.135) {
              descentY = Math.min(0.45, Math.max(descentY, p.y));
            }
            target = { x: pad.x, y: descentY, z: pad.z };
          }
        }
      }

      // 4. Smooth reference filter
      const alphaRef = phase === 'cross' || phase === 'exitLock' ? 0.16 : 0.10;
      const maxStep = phase === 'cross' || phase === 'exitLock' ? 0.032 : 0.024;
      ref.x += clamp((target.x - ref.x) * alphaRef, -maxStep, maxStep);
      ref.y += clamp((target.y - ref.y) * alphaRef, -maxStep, maxStep);
      ref.z += clamp((target.z - ref.z) * alphaRef, -maxStep, maxStep);

      // 3. Local position integrals & Yaw integral
      const distToTargetXZ = Math.hypot(target.x - p.x, target.z - p.z);
      if (distToTargetXZ < 0.35 && phase !== 'cross' && phase !== 'exitLock') {
        posInt.x = clamp(posInt.x + (target.x - p.x) * dt, -0.35, 0.35);
        posInt.z = clamp(posInt.z + (target.z - p.z) * dt, -0.35, 0.35);
      } else {
        posInt.x *= 0.985;
        posInt.z *= 0.985;
      }

      if (Math.abs(target.y - p.y) < 0.45) {
        posInt.y = clamp(posInt.y + (target.y - p.y) * dt, -0.6, 1.2);
      } else {
        posInt.y *= 0.99;
      }

      // Blend filtered reference and direct target error
      const ex = 0.65 * (ref.x - p.x) + 0.35 * (target.x - p.x);
      const ey = 0.65 * (ref.y - p.y) + 0.35 * (target.y - p.y);
      const ez = 0.65 * (ref.z - p.z) + 0.35 * (target.z - p.z);

      const dCompX = distSlow.x + 0.75 * (distFast.x - distSlow.x);
      const dCompY = distSlow.y + 0.50 * (distFast.y - distSlow.y);
      const dCompZ = distSlow.z + 0.75 * (distFast.z - distSlow.z);

      const kpXZ = phase === 'cross' || phase === 'exitLock' ? 5.2 : 4.5;
      const kdXZ = phase === 'cross' || phase === 'exitLock' ? 3.8 : 3.5;

      const ax = clamp(kpXZ * ex - kdXZ * vf.x + 1.8 * posInt.x + dragAcc * vf.x - dCompX, -3.8, 3.8);
      const az = clamp(kpXZ * ez - kdXZ * vf.z + 1.8 * posInt.z + dragAcc * vf.z - dCompZ, -3.8, 3.8);
      const ay = clamp(6.0 * ey - 3.8 * vf.y + 2.2 * posInt.y + dragAcc * vf.y - dCompY, -4.0, 5.0);

      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const totalY = Math.max(4.0, g + ay);
      let pitch = clamp(Math.atan2(cy * ax - sy * az, totalY), -0.48, 0.48);
      let roll = clamp(Math.atan2(-(sy * ax + cy * az), totalY), -0.48, 0.48);

      const tiltCos = Math.max(0.7, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp((nomMass * (g + ay)) / (16 * tiltCos), 0, 1);

      // Soft touchdown hold on pad
      if (obs.gateIndex === 3 && phase === 'descend') {
        const pad = obs.pad.centre;
        const padErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        if (p.y <= 0.092 && padErr <= 0.135) {
          pitch = clamp(pitch, -0.12, 0.12);
          roll = clamp(roll, -0.12, 0.12);
          if (p.y <= 0.078 && padErr <= 0.125 && Math.hypot(vf.x, vf.y, vf.z) < 0.35) {
            thrust = 0;
            pitch = 0;
            roll = 0;
          } else {
            thrust = Math.min(thrust, 0.22);
          }
        }
      }

      yawInt = clamp(yawInt + att.yaw * dt, -0.5, 0.5);
      const yawRate = clamp(-2.6 * att.yaw - 1.6 * yawInt - 0.15 * rates.yaw, -2, 2);

      lastThrust = thrust;
      return { thrust, roll, pitch, yawRate };
    },
  };
}

