      if (targetIndex !== obs.gateIndex) {
        if (targetIndex >= 0 && lockedGate) {
          lastPassedGate = { x: lockedGate.x, y: lockedGate.y, z: lockedGate.z };
        }
        if (targetIndex >= 0 && lockedGate && p.x < lockedGate.x + 0.28) {
          targetIndex = obs.gateIndex;
          phase = 'exitLock';
          exitTimer = 0;
        } else {
          targetIndex = obs.gateIndex;
          phase = obs.gateIndex < 3 ? 'align' : 'padHover';
          settle = 0;
          lockedGate = null;
          if (obs.gateIndex === 3) {
            descentY = Math.max(0.65, Math.min(0.9, p.y));
            posInt.x *= 0.3;
            posInt.z *= 0.3;
          }
        }
