          phase = obs.gateIndex < 3 ? 'align' : 'padHover';
          lockedGate = null;
          settle = 0;
          if (obs.gateIndex === 3) {
            descentY = Math.max(0.65, Math.min(0.9, p.y));
            posInt.x *= 0.3;
            posInt.z *= 0.3;
          }
        }
      }

      if (phase !== 'exitLock') {
        if (obs.gateIndex < 3) {
          const gate = obs.nextGate.centre;
          const errY = Math.abs(gate.y - p.y);
          const errZ = Math.abs(gate.z - p.z);
