  .replace("import { TASK, TAKEOFF, GATES, PAD, random, trialParameters } from '\''./task.mjs'\'';", "import { TASK, TAKEOFF, GATES, PAD, random, trialParameters } from '\''file:///workspace/tasks/drone/task.mjs'\''; import makeController from '\''file:///workspace/controller.js'\'';")
  .replace("const controller = new ControllerProcess(artifact);", "const ctrl = makeController(); const controller = { ready: async () => {}, step: async (obs) => { const a = ctrl.step(obs); return { thrust: clamp(a.thrust, 0, 1), roll: clamp(a.roll, -0.6, 0.6), pitch: clamp(a.pitch, -0.6, 0.6), yawRate: clamp(a.yawRate, -2, 2) }; }, close: () => {} };");
const mod = await import("data:text/javascript;base64," + Buffer.from(simCode).toString("base64"));
let passed = 0, total = 1000;
const fails = [];
for (let s = 1; s <= total; s++) {
  const { result } = await mod.runTrial("/workspace/controller.js", s);
  if (result.success) passed++;
